<h2>Build Google Search Console regex filters</h2><p class="lead">Turn a list of queries or URLs into a cleaner RE2-compatible regex for Custom (regex) filters.</p>
<div class="form-grid"><div class="field full"><label for="terms">Queries or URLs — one per line</label><textarea id="terms" style="min-height:190px" placeholder="seo tools\nseo tool\nfree seo tools"></textarea></div><div class="field"><label for="matchMode">Filter mode</label><select id="matchMode"><option value="match">Matches regex</option><option value="not">Doesn't match regex</option></select></div><div class="field"><label for="caseMode">Case sensitivity</label><select id="caseMode"><option value="insensitive">Not case-sensitive (default)</option><option value="sensitive">Case-sensitive</option></select></div><div class="field"><label for="anchorMode">Match scope</label><select id="anchorMode"><option value="partial">Partial match</option><option value="full">Full string</option><option value="start">Starts with</option><option value="end">Ends with</option></select></div><div class="field"><label for="dedupe">Normalize input</label><select id="dedupe"><option value="yes">Trim, remove blanks and duplicates</option><option value="no">Keep entered lines</option></select></div></div>
<div class="tool-actions"><button class="btn btn-primary" id="generate" type="button">Generate regex</button><button class="btn btn-secondary" id="copy" type="button">Copy regex</button></div><div class="result-box"><div class="field"><label for="regexOut">Google Search Console regex</label><textarea id="regexOut" readonly style="min-height:115px"></textarea></div><div class="result-grid"><div class="metric"><span>Items</span><strong id="count">0</strong></div><div class="metric"><span>Regex length</span><strong id="length">0</strong></div><div class="metric"><span>Syntax target</span><strong>RE2</strong></div></div></div><div class="notice"><strong>GSC behavior:</strong> Search Console uses RE2 syntax. Its default regex matching is partial and not case-sensitive; use anchors when you need start/end or full-string behavior. citeturn112108search0turn112108search2</div>
<script>(()=>{const $=i=>document.getElementById(i);const esc=s=>String(s).replace(/[\\^$.*+?()[\]{}|]/g,'\\$&');function items(){let a=$('terms').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if($('dedupe').value==='yes')a=[...new Set(a)];return a}function go(){const a=items();if(!a.length){$('regexOut').value='';$('count').textContent='0';$('length').textContent='0';return}let body=a.map(esc).join('|');if(a.length>1)body='(?:'+body+')';const s=$('anchorMode').value;if(s==='full')body='^'+body+'$';else if(s==='start')body='^'+body;else if(s==='end')body=body+'$';if($('caseMode').value==='sensitive')body='(?-i)'+body;$('regexOut').value=body;$('count').textContent=a.length;$('length').textContent=body.length}document.querySelectorAll('#terms,#matchMode,#caseMode,#anchorMode,#dedupe').forEach(x=>x.addEventListener('input',go));$('generate').onclick=go;$('copy').onclick=()=>tkCopy($('regexOut').value);go()})();</script>
